// Here you add mappings between the properties of the item objects and the inputs of the components.
// 'myComponentInput': 'myObjectProperty',
// 'anotherComponentInput': function () { return object.get('someProperty') + ' ' + object.get('otherProp') }
// These are the default mappings based on the selected template component.
map({
	'Index': 'Index',
	'Mounted': 'Mounted',
})

parameters.functionScript:
const total = Number(Inputs.TotalCount) || 0;
const pageSize = Math.max(1, Number(Inputs.PageSize) || 10);
const selectedPage = Math.max(0, Number(Inputs.SelectedPage) || 0);
const numPages = Math.max(1, Math.ceil(total / pageSize));

// Optional parts default to visible when the input is left unconnected
const showSummary = Inputs.ShowSummary === undefined ? true : !!Inputs.ShowSummary;
const showRowsPerPage = Inputs.ShowRowsPerPage === undefined ? true : !!Inputs.ShowRowsPerPage;
Outputs.ShowSummary = showSummary;
Outputs.ShowRowsPerPage = showRowsPerPage;

// How many direct page slots fit in the control
let _width = Number(Inputs.Width) - 214; // margins, prev/next buttons etc
if (isNaN(_width)) return;
if (showSummary) _width -= 150; // summary text
if (showRowsPerPage) _width -= 210; // label + selector

const numPageSlots = Math.min(Math.max(0, Math.floor(_width / 45)), numPages);

if (numPages > 1) {
    Outputs.LastPageIndex = numPages - 1;
    Outputs.LastPageVisible = true;
} else {
    Outputs.LastPageVisible = false;
}

const pages = [];

if (numPageSlots >= numPages - 2) {
    // All pages fit
    for (let p = 1; p < numPages - 1; p++) pages.push({
        id: Component.Object.id + '-' + p,
        Index: p
    });

    Outputs.LastEllipsis = false;
    Outputs.FirstEllipsis = false;
} else {
    let firstIndex = selectedPage;
    let lastIndex = selectedPage;
    while (lastIndex - firstIndex < numPageSlots - 1) {
        firstIndex = Math.max(1, firstIndex - 1);
        lastIndex = Math.min(numPages - 2, lastIndex + 1);
    }

    let lastEllipsis = false;
    if (lastIndex < numPages - 2) {
        // We did not reach the last page, make room for ...
        lastIndex--;
        lastEllipsis = true;
    }

    let firstEllipsis = false;
    if (firstIndex > 1) {
        // We did not reach the first page, make room for ...
        firstIndex++;
        firstEllipsis = true;
    }

    for (let p = firstIndex; p <= lastIndex; p++) pages.push({
        id: Component.Object.id + '-' + p,
        Index: p
    });

    Outputs.LastEllipsis = lastEllipsis;
    Outputs.FirstEllipsis = firstEllipsis;
}

Component.Object.NumPages = numPages;
Component.Object.Skip = selectedPage * pageSize;

Outputs.BackEnabled = selectedPage > 0;
Outputs.NextEnabled = selectedPage < numPages - 1;

Outputs.Pages = pages;

if(Component.Object['Selected Page'] < Component.Object.NumPages-1)
    Component.Object['Selected Page']++;

Outputs.Changed();

const raw = Inputs.RowsPerPageOptions;
const options = Array.isArray(raw) && raw.length > 0
    ? raw
    : [5, 10, 15, 20, 30, 40, 50];

Outputs.Items = options.map((p) => ({
    Label: '' + p,
    Value: '' + p
}));

const rowsPerPage = parseInt(Inputs.Value, 10);
if (!isNaN(rowsPerPage) && rowsPerPage > 0) {
    Component.Object.RowsPerPage = rowsPerPage;
}

Outputs.Changed();

const total = Number(Inputs.TotalCount);
const pageSize = Math.max(1, Number(Inputs.RowsPerPage) || 10);
const page = Math.max(0, Number(Inputs.SelectedPage) || 0);

if (isNaN(total) || total <= 0) {
    Outputs.Text = 'Showing 0 of 0';
    return;
}

// Keep the selected page inside the document when the page size grows
const numPages = Math.max(1, Math.ceil(total / pageSize));
if (Component.Object['Selected Page'] > numPages - 1) {
    Component.Object['Selected Page'] = numPages - 1;
}

const startRow = Math.min(page * pageSize, total - 1);
const endRow = Math.min(startRow + pageSize, total);

Outputs.Text = 'Showing ' + (startRow + 1) + '\u2013' + endRow + ' of ' + total;

if (Inputs.Selected) {
    Outputs.BgColor = 'var(--primary)';
    Outputs.TextColor = 'var(--primary-foreground)';
} else if (Inputs.Hover) {
    Outputs.BgColor = 'var(--muted)';
    Outputs.TextColor = 'var(--foreground)';
} else {
    Outputs.BgColor = 'transparent';
    Outputs.TextColor = 'var(--foreground)';
}
